import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"周易尚氏學 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"周易尚氏學 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"classics/shangshi/009.md","filePath":"classics/shangshi/009.md"}'),s={name:"classics/shangshi/009.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>艮少。坎隱伏不明。故名曰蒙。蒙樨也。不明也。二得中有應故亨。艮為童蒙。為求。而二至上正反艮。自二言若求五。自五言若求二。有互相求之象。然二陽也。陽大明。五陰也陰迷。我謂二。匪我求童蒙。童蒙求我者。言二不必求五。五自來應二也。傳曰志應。言二五相應與相上下也。舊解詁實匪字。定謂二不應五者非也。坎為聖為通故為筮。比曰原筮。亦以坎為筮。震為言。放曰告。而二至上正反震。言多。故曰瀆。瀆褻瀆也。震反為艮。艮止故不告。昔賢說此。總不知再三瀆之故何在。由正覆象並用之義。失傳故也。又筮象亦失傳。故初筮不知何所指。豈知坎在下故曰初筮。專指九二。艮坎皆冬日卦。故曰利貞。</p><p>彖曰。蒙。山下有險。險而止。蒙。蒙亨。以亨行。時中也。匪我求童蒙。童蒙求我。志應也。初筮告。以剛中也。再三瀆。瀆則不告。瀆蒙也。蒙以養正。聖功也。</p><p>志應。言二五互求也。坎為聖。故曰聖功。</p><p>象曰。山下出泉。蒙。君子以果行育德。</p><p>艮為君子。為堅。為果。震為行。故曰果行。果行者。言堅定不易也。傳曰。致果為毅。是其義也。震為生為德。故曰育德。以者。法也。言君子法蒙象。而果毅其行。養育其德也。</p><p>初六。發矇。利用刑人。用說桎梏。以往吝。</p><p>發啟也。詩大雅。思齊篇曰。刑于寡妻。左傳襄十三年。一人刑善。數世賴之。注皆訓刑為法。是刑與型同。利用刑人者。言宜樹之模型。使童蒙有所法式。得為成人。永免罪闢也。坎為桎梏。說文。桎足械。梏手械。四無應。故往吝。說文引作遴。雲行難也。吝遴古通。漢書魯安王傳。晚節遴。王莽傳。性實遴嗇。義皆為吝。以往。王安石。朱震。王宗傳。朱子。皆訓為以後。大誤。</p><h3 id="象曰。利用刑人。以正法也。" tabindex="-1">象曰。利用刑人。以正法也。 <a class="header-anchor" href="#象曰。利用刑人。以正法也。" aria-label="Permalink to “象曰。利用刑人。以正法也。”">​</a></h3><p>正平也。坎為平。故曰正法。言以法則示人。俾童蒙有所則效。即釋刑人之義也。</p><p>九二。苞蒙。吉。納婦。吉。子克家。</p><p>陽居陰中。故曰苞蒙。五陰來應。故曰納婦吉。震為子。艮為家。五艮體。二應之。故曰子克家。克者能也。言能任家事也。</p><h3 id="象曰。子克家。剛柔接也。" tabindex="-1">象曰。子克家。剛柔接也。 <a class="header-anchor" href="#象曰。子克家。剛柔接也。" aria-label="Permalink to “象曰。子克家。剛柔接也。”">​</a></h3><p>接與龍戰於野戰字義同。言交接也。</p><p>六三。勿用取女。見金夫。不有躬。無攸利。</p><p>取娶同。坤為女。見金夫。不用躬。申勿用之故也。金夫者美稱。詩有匪君子。如金如錫。如圭如璧。左傳。思我王度。式如玉。式如金。皆以金喻人之美。艮為金。為夫。人徒知乾為金。不知艮堅亦為金。易林隨之屯雲。金玉滿堂。以屯之互艮為金也。人徒知震有夫象。不知三男皆為夫。比曰後夫兇。以艮為夫也。易林復之剝雲。夫亡從軍。以剝上艮為夫也。三與上艮應。故曰見金夫。坤為躬。三體震。震為行而決躁。故見金夫而亟欲往上。不顧四五之阻。故曰不有躬。女行如此。不順。故無所利也。</p><h3 id="象曰。勿用取女。行不順也。" tabindex="-1">象曰。勿用取女。行不順也。 <a class="header-anchor" href="#象曰。勿用取女。行不順也。" aria-label="Permalink to “象曰。勿用取女。行不順也。”">​</a></h3><p>坤為順。震躁動。故不順。案此爻舊解。虞翻以陽為金。謂三為二所淫。朱子謂金夫。蓋以金賂己而挑之。若魯秋胡之事。均堪噴飯。若夫王弼以金夫為剛夫。毛大可惠棟等用卦變。又以兌陽為金。皆非。故夫卦象一失傳。無論若何揣測。皆不能當。其關係之重若是。</p><p>六四。困蒙。吝。</p><p>四無應。承乘皆失類。故曰困。</p><h3 id="象曰。困蒙之吝。獨遠實也。" tabindex="-1">象曰。困蒙之吝。獨遠實也。 <a class="header-anchor" href="#象曰。困蒙之吝。獨遠實也。" aria-label="Permalink to “象曰。困蒙之吝。獨遠實也。”">​</a></h3><p>實為陽。初三五皆近陽。四獨否。故曰獨遠實。</p><p>六五。童蒙吉。</p><p>艮為童蒙。上承陽。下應二。雖不當位。而居中。故吉。</p><h3 id="象曰。童蒙之吉。順以巽也。" tabindex="-1">象曰。童蒙之吉。順以巽也。 <a class="header-anchor" href="#象曰。童蒙之吉。順以巽也。" aria-label="Permalink to “象曰。童蒙之吉。順以巽也。”">​</a></h3><p>上承陽。順陽而行。下與二相上下。故曰順以巽。</p><p>上九。擊蒙。不利為寇。利禦寇。</p><p>艮手為擊。亦啟發之意。上應在三。三坎為寇。道窮於上。故不利為寇。然艮為堅為守。下擁群陰。勢眾。故利禦寇。坎彖傳雲。王公設險以守其國。守謂互艮也。能守故利。</p><h3 id="象曰。利用禦寇。上下順也。" tabindex="-1">象曰。利用禦寇。上下順也。 <a class="header-anchor" href="#象曰。利用禦寇。上下順也。" aria-label="Permalink to “象曰。利用禦寇。上下順也。”">​</a></h3><p>君子守其前。小人隨其後。故利禦寇。上下順者。言坤民順上也。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
